insert into public.research_outputs (id, request_id, output, bibtex, apa, model, status, created_at) values ('b9ed1ca1-1f34-59a3-a829-cec38fa3296b', '88aef3ff-53e8-5bfa-843b-acc2d9456277', '{"schema_version":"1.0","request_id":"88aef3ff-53e8-5bfa-843b-acc2d9456277","query":"spaced repetition matematik","expanded_queries":["spaced repetition mathematics learning","distributed practice math achievement","aralıklı tekrar matematik öğrenme","interleaved practice mathematics problems"],"synthesis":[{"text":"Aralıklı çalışma, aynı sürenin tek oturumda toplanmasına göre uzun süreli hatırlamayı güvenilir biçimde artırır; etki, tekrarlar arasındaki aralık sınav tarihine göre ayarlandığında en yüksektir.","cites":[1,3]},{"text":"Matematikte problem türlerinin karıştırılarak ve aralıklı çalışılması, aynı türün art arda çözülmesine göre gecikmeli testte daha iyi sonuç vermiştir.","cites":[2,4]}],"citations":[{"ordinal":1,"doi":"10.1037/0033-2909.132.3.354","title":"Distributed practice in verbal recall tasks: A review and quantitative synthesis","authors":"Cepeda, Nicholas J.; Pashler, Harold; Vul, Edward; Wixted, John T.; Rohrer, Doug","venue":"Psychological Bulletin","year":2006,"crossref_status":"verified","title_similarity":0.98,"verified_at":"2026-10-18T00:20:00Z","oa_pdf_url":null,"tldr":"Aralıklı çalışma, toplu çalışmaya göre uzun süreli hatırlamayı artırır.","source":"openalex"},{"ordinal":2,"doi":"10.1007/s11251-007-9015-8","title":"The shuffling of mathematics problems improves learning","authors":"Rohrer, Doug; Taylor, Kelli","venue":"Instructional Science","year":2007,"crossref_status":"verified","title_similarity":0.97,"verified_at":"2026-10-18T00:20:00Z","oa_pdf_url":"https://example.org/oa/rohrer-2007.pdf","tldr":"Karışık sıralanmış matematik problemleri gecikmeli testte daha iyi sonuç verir.","source":"openalex"},{"ordinal":3,"doi":"10.1177/1529100612453266","title":"Improving Students'' Learning With Effective Learning Techniques: Promising Directions From Cogn